#!/usr/bin/env python3
"""
Round 150b (culprits), 4 October 2026. Needs round 149b.

Adds the Autumn woodlands basemap.

Run from the repository root (the apply-patch workflow does).
"""
import base64, pathlib, subprocess, sys, tempfile

NOTES = ["## Round 150b (4 October)\n\nNeeds round 149b. No tiles patch. No app.js?v= bump. One new basemap.\n\n- Autumn woodlands, a sixth basemap (asked 4 October: as close as can be to a\n  Robert Griffing painting, 18th-century Eastern Woodlands, fall warmth, soft\n  hazy light). Nothing copied from any painting; the look only: hardwoods in\n  fall painted as dappled leaf masses (russet, sienna, amber, ochre, deep\n  crimson) with dark evergreen stands, each lit upper left by a low sun; warm\n  cream light and violet-grey shadow from the south-west (Mapterhorn); warm\n  mist lying level in the valleys and over water, far ridges fading to hazy\n  blue-grey (AWS heights); still silvery water; a warm hazy sky on the globe.\n- Leaves painted square by square on the reader's computer (woodbrush://,\n  woodBrushPiece), only on land below about 2,600 m, read from the AWS height\n  square (woodHeights); seamless across edges. About 140 ms a square in node.\n- The no-orange/no-yellow rule is set aside for this basemap only (fall warmth\n  asked for): muted earth colours, no green, nothing loud (tested). Layers\n  outline-wood-* (WOOD_IDS), one block (\"Autumn woodlands, a sixth basemap\"\n  to \"end of Autumn woodlands\"), after Hell. Not seen against real tiles.\n"]


def git(*a, check=True):
    return subprocess.run(["git", *a], capture_output=True, text=True, check=check)


def main():
    root = pathlib.Path(".")
    if not (root / "map" / "app.js").exists():
        sys.exit("round150b: run from the culprits repository root")
    h = root / "HANDOFF.md"
    if "## Round 149b" not in h.read_text(encoding="utf-8"):
        sys.exit("round150b: round 149b must be applied first")
    with tempfile.NamedTemporaryFile("wb", suffix=".diff", delete=False) as f:
        f.write(base64.b64decode(DIFF))
        path = f.name
    if git("apply", "--check", "-R", "--binary", path, check=False).returncode == 0:
        print("round150b: already applied")
    else:
        r = git("apply", "--3way", "--binary", path, check=False)
        if r.returncode != 0:
            git("checkout", "--", "map/app.js", "map/test.mjs", check=False)
            sys.exit("round150b: the diff did not apply:\n" + r.stdout + r.stderr)
        print("round150b: applied")
    text = h.read_text(encoding="utf-8")
    add = "".join(n if n.endswith("\n\n") else n.rstrip("\n") + "\n\n" for n in NOTES if n.split("\n", 1)[0] not in text)
    if add:
        at = text.index("\n## Round ") + 1
        h.write_text(text[:at] + add + text[at:], encoding="utf-8")


DIFF = ''

if __name__ == "__main__":
    main()
